%------------ Cauchy's Theorem Content ---------------
\begin{tikzpicture}
\node [mybox] (box){%
    \begin{minipage}{0.3\textwidth}
    \textbf{Cauchy's Theorem}: If $G$ is a finite group and $p$ is a prime dividing $|G|$ then $G$ has an element of order $p$.
    \end{minipage}
};
