    \begin{minipage}{0.3\textwidth}
    \begin{align*}
  v_{1} &= x_{1} \\
  v_{2} &= x_{2} - \frac{\langle x_2, v_1\rangle}{||v_{1}||^2}v_{1}\\
  &\shortvdotswithin{=} 
  v_{n} &= x_{m} - \sum_{k=1}^{m-1} \frac{\langle x_{m},v_{k} \rangle}{||v_{k}||^{2}}v_{k} 
    \end{align*}
    \end{minipage}
};
