    \begin{minipage}{0.3\textwidth}
    	\begin{align*}
        	F(x) &= y'' + y' \\
            y_h &= b_1y_1(x) + b_2y_2(x), y_1 y_2 \text{ are L.I.} \\
            y_p &= u_1(x)y_1(x) + u_2(x)y_2(x) \\
            u_1 &= \int^t -\frac{y_2F(t)dt}{w[y_1,y_2](t)} \\
            u_2 &= \int^t \frac{y_1F(t)dt}{w[y_1,y_2](t)} \\    		
            y &= y_h + y_p
    	\end{align*}
    \end{minipage}
};
