        \hline
        $e^x$ & $\sum_{n=0}^{\infty} x^n/{n!}$ \\ \hline
        $\sin x$ & $\sum_{n=0}^{\infty} \frac{(-1)^n}{(2n+1)!}x^{2n+1}$ \\ \hline
        $\cos x$ & $\sum_{n=0}^{\infty} \frac{(-1)^n}{(2n)!}x^{2n}$ \\
	\end{tabular}}
